    if($j.toolsTokens){$tt=$j.toolsTokens}
    Write-Output ("FILE "+$f.Name+"  mtime "+$f.LastWriteTime.ToString('HH:mm:ss'))
    Write-Output ("  keys: "+(($j.PSObject.Properties.Name) -join ','))
  } catch { Write-Output ("  parse fail "+$f.Name+": "+$_.Exception.Message) }
}

$dir="$env:USERPROFILE\.dsh\storages\session_projcache\sessions"
function Show($f){
 $j = Get-Content $f.FullName -Raw | ConvertFrom-Json; $row = $j.record.rows
 Write-Output ("== "+$f.Name+"  mtime "+$f.LastWriteTime.ToString('HH:mm:ss'))
 Write-Output ("  agentPreset: "+($row.agentPreset | ConvertTo-Json -Compress -Depth 3))
 Write-Output ("  tokenUsage: "+($row.tokenUsage | ConvertTo-Json -Compress -Depth 3))
 Write-Output ("  contextBreakdown: "+($row.contextBreakdown | ConvertTo-Json -Compress -Depth 2))
}
# check 3 newest
Get-ChildItem $dir -Filter *.json | Sort-Object LastWriteTime -Descending | Select-Object -First 3 | ForEach-Object { Show $_ }

