$out = & dsh --profile web --dump-config 2>&1
# 找所有 preset-standard 与 full-tools 锚点行
for($i=0;$i -lt $out.Count;$i++){
  if($out[$i] -match 'id:\s*preset-standard' -or $out[$i] -match 'id:\s*preset-full-tools' -or $out[$i] -match 'id:\s*preset-ptc' -or $out[$i] -match 'id:\s*preset-cordis' -or $out[$i] -match 'id:\s*preset-minimal'){
    Write-Output (($i+1).ToString()+": "+$out[$i].Trim())
  }
}

$out = & dsh --profile web --dump-config 2>&1
$seg = $out[1000..1210]
for($i=0;$i -lt $seg.Count;$i++){
  $line=$seg[$i]
  if($line -match 'id:\s*(tool-schedule|tool-goal|tool-workflow|tool-subagent)'){
    $abs = 1001+$i
    # look at next 3 lines for disabled
    $ctx = ($seg[($i)..([math]::Min($i+2,$seg.Count-1))] | ForEach-Object { $_.Trim() }) -join ' | '
    Write-Output ("L$abs : $ctx")
  }
}

